/* 不用 LET：重复计算 VLOOKUP 两次 */
=IF(VLOOKUP(A2, $B$2:$D$500, 3, FALSE) > 100,
    VLOOKUP(A2, $B$2:$D$500, 3, FALSE) * 1.1,
    VLOOKUP(A2, $B$2:$D$500, 3, FALSE) * 0.9)

/* 用 LET：只查一次，复用结果 */
=LET(
    查找结果, XLOOKUP(A2, $B$2:$B$500, $D$2:$D$500, 0),
    IF(查找结果 > 100, 查找结果 * 1.1, 查找结果 * 0.9)
)

/* 先筛选，再查找，最后判断 */
=LET(
    合格记录, FILTER(A2:E500, D2:D500="合格"),
    目标行, XLOOKUP(A2, INDEX(合格记录, 0, 2), INDEX(合格记录, 0, 5), ""),
    IF(目标行="", "无合格记录", 目标行)
)

/* 定义一个计算含税价格的函数 */
=LAMBDA(价格, 税率, ROUND(价格 * (1 + 税率), 2))(100, 0.13)
/* 返回 113.00 */

/* 定义一个判断等级的函数 */
=LAMBDA(分数,
    IFS(分数 >= 90, "优秀",
        分数 >= 80, "良好",
        分数 >= 60, "及格",
        TRUE, "不及格")
)(A2)

/* 步骤：公式 → 名称管理器 → 新建 */
/* 名称：含税价格 */
/* 引用位置：=LAMBDA(价格, 税率, ROUND(价格 * (1 + 税率), 2)) */

/* 之后在任意单元格直接使用 */
=含税价格(100, 0.13)           /* 返回 113.00 */
=含税价格(B2, 0.06)            /* 对 B2 按 6% 税率计算 */

/* 1. 安全除法（防除零） */
/* 名称：安全除法 */
=LAMBDA(被除数, 除数, IF(除数 = 0, 0, ROUND(被除数 / 除数, 2)))

/* 2. 多条件查找并返回指定列 */
/* 名称：多条件查找 */
=LAMBDA(查找值1, 查找值2, 查找区域1, 查找区域2, 返回区域,
    LET(
        匹配行, (查找区域1 = 查找值1) * (查找区域2 = 查找值2),
        FILTER(返回区域, 匹配行, "未找到")
    )
)

/* 3. 取第N大的不重复值 */
/* 名称：第N大唯一值 */
=LAMBDA(区域, N, LARGE(UNIQUE(区域), N))

/* 4. 模糊匹配查找 */
/* 名称：模糊查找 */
=LAMBDA(关键词, 查找区域, 返回区域,
    LET(
        匹配, ISNUMBER(SEARCH(关键词, 查找区域)),
        FILTER(返回区域, 匹配, "未找到")
    )
)

/* 名称：计算阶乘 */
/* 引用位置：=LAMBDA(n, IF(n <= 1, 1, n * 计算阶乘(n - 1))) */

=计算阶乘(5)    /* 返回 120 */

/* 名称：斐波那契数列 */
/* 引用位置：=LAMBDA(n, IF(n <= 2, 1, 斐波那契(n-1) + 斐波那契(n-2))) */

=斐波那契(10)   /* 返回 55 */

/* 对每个值乘以 1.1 */
=MAP(A2:A10, LAMBDA(x, x * 1.1))

/* 对每个值判断是否大于平均 */
=MAP(A2:A10, LAMBDA(x, IF(x > AVERAGE(A2:A10), "高", "低")))

/* 每个值加上前缀 */
=MAP(A2:A10, LAMBDA(x, "M-" & x))

/* 两个数组对应位置相乘 */
=MAP(A2:A10, B2:B10, LAMBDA(数量, 单价, 数量 * 单价))

/* 三个数组组合判断 */
=MAP(A2:A10, B2:B10, C2:C10, LAMBDA(组别, 状态, 产量,
    组别 & "-" & 状态 & "-" & 产量
))

/* 对 A 列每个编号查找对应的重量 */
=MAP(A2:A50, LAMBDA(编号,
    XLOOKUP(编号, Sheet1!$B$2:$B$500, Sheet1!$G$2:$G$500, 0)
))

/* 比逐行写 XLOOKUP 更简洁，一个公式搞定整列 */

/* 对每行数据拼接后合并 */
=LET(
    拼接结果, MAP(A2:A10, B2:B10, LAMBDA(组, 状态, 组 & ":" & 状态)),
    TEXTJOIN(", ", TRUE, 拼接结果)
)
/* 结果如 "挤压组:合格, 挤压组:不合格, 包装组:合格" */

/* 截止当前的最高值（股票最高价常用） */
=SCAN(0, B2:B30, LAMBDA(当前最高, 今日值, MAX(当前最高, 今日值)))
/* 返回截止每个时点的历史最高值 */

/* 标记连续合格：一旦不合格，标记中断 */
=SCAN(TRUE, B2:B30, LAMBDA(前序结果, 当前状态, 前序结果 * (当前状态 = "合格")))
/* 返回 TRUE, TRUE, FALSE, FALSE, ...
   一旦遇到"不合格"，后面全部为 FALSE */

/* 按组别累计产量 */
=LET(
    组别列, A2:A30,
    产量列, B2:B30,
    SCAN(0, SEQUENCE(ROWS(组别列)), LAMBDA(累计, 行号,
        LET(
            当前组, INDEX(组别列, 行号),
            前一组, IF(行号 > 1, INDEX(组别列, 行号 - 1), ""),
            IF(当前组 = 前一组, 累计 + INDEX(产量列, 行号), INDEX(产量列, 行号))
        )
    ))
)
/* 每组重新开始累计 */

/* 截止当前的平均值 */
=SCAN(0, A2:A30, LAMBDA(累计, 当前, 累计 + 当前))
/ SEQUENCE(ROWS(A2:A30), 1, 1, 1)
/* 累计求和数组 ÷ 序号数组 = 运行平均 */

/* 求和（等价于 SUM） */
=REDUCE(0, A2:A10, LAMBDA(总和, 当前, 总和 + 当前))

/* 求积 */
=REDUCE(1, A2:A10, LAMBDA(乘积, 当前, 乘积 * 当前))

/* 找最大值 */
=REDUCE(0, A2:A10, LAMBDA(当前最大, 当前, MAX(当前最大, 当前)))

/* 筛选大于平均值的记录 */
=DROP(
    REDUCE("", A2:A10,
        LAMBDA(结果, 当前,
            IF(当前 > AVERAGE(A2:A10),
               VSTACK(结果, 当前),
               结果)
        )
    ),
    1   /* 去掉初始的空字符串行 */
)

/* 筛选包含"模具"的记录 */
=DROP(
    REDUCE("", B2:B50,
        LAMBDA(结果, 当前,
            IF(ISNUMBER(SEARCH("模具", 当前)),
               VSTACK(结果, 当前),
               结果)
        )
    ),
    1
)

/* 将以"A"开头的值合并为逗号分隔 */
=TEXTBEFORE(
    REDUCE("", A1:A5,
        LAMBDA(文本, 当前,
            IF(LEFT(当前, 1) = "A",
               文本 & 当前 & ",",
               文本)
        )
    ),
    ","
)
/* 去掉末尾多余的逗号 */

/* 将多个工作表的数据垂直合并 */
=DROP(
    REDUCE(
        VSTACK({"表名","数据"}),
        HSTACK(Sheet1!A2:A10, Sheet2!A2:A10, Sheet3!A2:A10),
        LAMBDA(合并结果, 当前块,
            VSTACK(合并结果, 当前块)
        )
    ),
    1
)

/* 逐行检查：如果产量>100且状态="合格"，累加1，否则不累加 */
=REDUCE(0, A2:A50,
    LAMBDA(计数, 当前产量,
        LET(
            行号, XMATCH(当前产量, A2:A50),
            状态, INDEX(D2:D50, 行号),
            IF(AND(当前产量 > 100, 状态 = "合格"),
               计数 + 1,
               计数)
        )
    )
)

/* 对每行求和 */
=BYROW(A2:E10, LAMBDA(行, SUM(行)))
/* 返回一列，每行是 A2:E2、A3:E3... 的和 */

/* 对每行取最大值 */
=BYROW(A2:E10, LAMBDA(行, MAX(行)))

/* 对每行计算合格率 */
=BYROW(A2:E10, LAMBDA(行,
    COUNTIF(行, "合格") / COLUMNS(行)
))

/* 每列的平均值 */
=BYCOL(A2:E30, LAMBDA(列, AVERAGE(列)))

/* 每列的非空计数 */
=BYCOL(A2:E30, LAMBDA(列, COUNTA(列)))

/* 筛选"行最大值>100"的行 */
=FILTER(A2:E10,
    BYROW(A2:E10, LAMBDA(行, MAX(行) > 100))
)

/* 筛选"行中有不合格"的行 */
=FILTER(A2:E10,
    BYROW(A2:E10, LAMBDA(行, COUNTIF(行, "不合格") > 0))
)

/* 生成 3×3 的乘法表 */
=MAKEARRAY(3, 3, LAMBDA(r, c, r * c))
/* 返回:
   1  2  3
   2  4  6
   3  6  9  */

/* 生成 5×1 的序号列 */
=MAKEARRAY(5, 1, LAMBDA(r, c, r))
/* 返回 {1; 2; 3; 4; 5} */

/* 8×8 棋盘格（交替黑白） */
=MAKEARRAY(8, 8, LAMBDA(r, c,
    IF(MOD(r + c, 2) = 0, "■", "□")
))

/* 行=日期，列=班次，内容=日期+班次组合 */
=MAKEARRAY(7, 3, LAMBDA(行, 列,
    TEXT(DATE(2026, 8, 行), "m/d") & " " & CHOOSE(列, "早班", "中班", "晚班")
))

/* 垂直拼接（上下合并） */
=VSTACK(A2:A10, B2:B10)        /* 两列上下合并为一列 */
=VSTACK(Sheet1!A2:E10, Sheet2!A2:E10)   /* 两表上下合并 */

/* 水平拼接（左右合并） */
=HSTACK(A2:A10, B2:B10)        /* 两列左右合并为两列 */

/* 带表头拼接 */
=VSTACK(
    HSTACK({"编号","名称","状态"}),
    HSTACK(A2:A10, B2:B10, C2:C10)
)

/* 将二维数组转为单列（按列扫描） */
=TOCOL(A1:C5)
/* 默认按列扫描：A1,A2,A3,A4,A5,B1,B2,... */

/* 按行扫描 */
=TOCOL(A1:C5, , TRUE)
/* A1,B1,C1,A2,B2,C2,... */

/* 忽略空值和错误 */
=TOCOL(A1:C5, 3)              /* 1=忽略空, 2=忽略错误, 3=都忽略 */

/* 取前N行 */
=TAKE(A1:E10, 3)              /* 取前3行 */
=TAKE(A1:E10, -3)             /* 取后3行 */

/* 取前N列 */
=TAKE(A1:E10, , 2)            /* 取前2列 */
=TAKE(A1:E10, , -1)           /* 取最后1列 */

/* 删前N行 */
=DROP(A1:E10, 1)              /* 去掉表头 */
=DROP(A1:E10, -1)             /* 去掉最后一行 */

/* 取第2、4、5列 */
=CHOOSECOLS(A1:E10, 2, 4, 5)

/* 取第1、3行 */
=CHOOSEROWS(A1:E10, 1, 3)

/* 用 MATCH 动态选列 */
=CHOOSECOLS(A1:E10, XMATCH("模具编号", A1:E1), XMATCH("状态", A1:E1))
/* 根据表头名称动态选择列 */

/* 将多列数据合并为一列并去重排序 */
=SORT(UNIQUE(TOCOL(A2:C50)))

/* 将宽表转为长表（逆透视） */
=LET(
    数据, A1:C10,
    表头, TAKE(数据, 1),
    内容, DROP(数据, 1),
    VSTACK(
        HSTACK({"行号","列名","值"}),
        DROP(
            REDUCE("", SEQUENCE(ROWS(内容)),
                LAMBDA(结果, r,
                    VSTACK(结果,
                        HSTACK(
                            SEQUENCE(COLUMNS(内容), 1, r, 0),
                            TRANSPOSE(表头),
                            TRANSPOSE(INDEX(内容, r, 0))
                        )
                    )
                )
            ),
            1
        )
    )
)

/* 按组别汇总产量 */
=GROUPBY(B2:B500, E2:E500, SUM, 3)
/* 参数3=显示表头+总计行 */

/* 按组别汇总多列 */
=GROUPBY(B2:B500, HSTACK(E2:E500, G2:G500), SUM, 3)

/* 按组别+状态汇总产量 */
=GROUPBY(HSTACK(B2:B500, D2:D500), E2:E500, SUM, 3)

/* 使用自定义聚合函数 */
=GROUPBY(B2:B500, E2:E500,
    LAMBDA(x, ROUND(AVERAGE(x), 2)),  /* 平均值保留2位 */
    3)

/* 行=组别, 列=状态, 值=产量求和 */
=PIVOTBY(B2:B500, D2:D500, E2:E500, SUM, 3)

/* 行=组别, 列=月份, 值=平均产量 */
=PIVOTBY(
    B2:B500,                    /* 行字段 */
    TEXT(F2:F500, "yyyy-mm"),   /* 列字段（日期按月分组） */
    E2:E500,                     /* 值字段 */
    AVERAGE,                     /* 聚合函数 */
    3                            /* 显示表头和总计 */
)

/* 完全替代透视表，且数据更新后自动刷新 */

/* 根据输入的组别，动态返回该组所有合格记录的编号和产量 */
=LET(
    目标组, A1,                          /* A1 是下拉选框 */
    筛选结果, FILTER(A2:E500, (B2:B500=目标组) * (D2:D500="合格")),
    CHOOSECOLS(筛选结果, 1, 5)           /* 只返回编号和产量列 */
)

/* 在两个不同区域中查找，返回第一个找到的结果 */
=LET(
    结果1, XLOOKUP(A2, Sheet1!B:B, Sheet1!D:D, ""),
    结果2, XLOOKUP(A2, Sheet2!A:A, Sheet2!C:C, ""),
    IF(结果1 <> "", 结果1, 结果2)
)

/* 用 LAMBDA 封装为自定义函数 */
/* 名称：双区域查找 */
=LAMBDA(查找值, 区域1查找列, 区域1返回列, 区域2查找列, 区域2返回列,
    LET(
        r1, XLOOKUP(查找值, 区域1查找列, 区域1返回列, ""),
        IF(r1 <> "", r1, XLOOKUP(查找值, 区域2查找列, 区域2返回列, "未找到"))
    )
)

/* 累计产量 + 环比增长标记 */
=LET(
    产量, E2:E50,
    日期, F2:F50,
    累计, SCAN(0, 产量, LAMBDA(s, c, s + c)),
    环比, MAP(累计, LAMBDA(x,
        IF(x = 0, "—", "增长" )
    )),
    HSTACK(日期, 产量, 累计, 环比)
)

/* 根据 A 列多个编号，查找每个编号对应的组别，合并为逗号分隔 */
=LET(
    编号列表, TEXTSPLIT(A2, ","),
    查找结果, MAP(编号列表, LAMBDA(编号,
        XLOOKUP(编号, $B$2:$B$500, $C$2:$C$500, "?")
    )),
    TEXTJOIN(",", TRUE, 查找结果)
)
/* A2 = "M001,M002,M003" → "挤压1组,挤压2组,包装组" */

/* 获取唯一组别列表，按字母排序，并用"—"补齐到5个 */
=LET(
    唯一值, SORT(UNIQUE(B2:B500)),
    补齐数, 5 - ROWS(唯一值),
    IF(补齐数 > 0,
        VSTACK(唯一值, EXPAND("—", 补齐数, 1, "—")),
        唯一值
    )
)

/* 将按月排列的数据转置为长表 */
=LET(
    原始, A1:D13,                    /* A列=项目, B-D列=1-3月 */
    表头, DROP(TAKE(原始, 1), , 1),  /* {"1月","2月","3月"} */
    项目, DROP(原始, 1),             /* 去掉表头 */
    项目名, INDEX(项目, 0, 1),
    月度数据, DROP(项目, , 1),        /* 去掉项目名列 */
    VSTACK(
        HSTACK({"项目","月份","值"}),
        DROP(REDUCE("", SEQUENCE(ROWS(项目)),
            LAMBDA(结果, r,
                VSTACK(结果,
                    HSTACK(
                        SEQUENCE(COLUMNS(月度数据), 1, INDEX(项目名, r), 0),
                        TRANSPOSE(表头),
                        TRANSPOSE(INDEX(月度数据, r, 0))
                    )
                )
            )
        ), 1)
    )
)

/* 问题：目标区域有数据，报 #SPILL! */
=MAP(A2:A10, LAMBDA(x, x * 2))    /* 如果 B2:B10 有值，溢出失败 */

/* 解决：清空目标区域，或用 IFERROR 包裹 */

/* 错误1：忘记调用参数 */
=LAMBDA(x, x * 2)                 /* 只返回 LAMBDA 定义，不计算 */
=LAMBDA(x, x * 2)(5)              /* 正确：返回 10 */

/* 错误2：参数数量不匹配 */
=MAP(A2:A10, B2:B10, LAMBDA(x, x * 2))  /* 两个数组但 LAMBDA 只接收1个参数 */
=MAP(A2:A10, B2:B10, LAMBDA(x, y, x * y))  /* 正确 */

/* 错误3：递归无终止条件 */
/* 名称：无限循环 */
=LAMBDA(n, 无限循环(n + 1))     /* 会报循环引用错误 */

/* 正确：有终止条件 */
=LAMBDA(n, IF(n >= 10, n, 无限循环(n + 1)))

/* 错误：变量名与单元格引用冲突 */
=LET(A1, 100, A1 * 2)            /* A1 是有效单元格引用，冲突！ */

/* 正确：用描述性名称 */
=LET(基础值, 100, 基础值 * 2)

/* 正确：用中文变量名（推荐） */
=LET(含税, 100 * 1.13, 含税 * 0.87)

/* 筛选挤压组所有记录 */
=FILTER(A2:E500, B2:B500="挤压组")

/* 找不到时返回提示而非 #CALC! */
=FILTER(A2:E500, B2:B500="挤压组", "无匹配记录")

/* AND 关系：用 * 连接条件 */
=FILTER(A2:E500, (B2:B500="挤压组") * (D2:D500="合格"))

/* OR 关系：用 + 连接条件 */
=FILTER(A2:E500, (B2:B500="挤压组") + (B2:B500="包装组"))

/* AND + OR 混合 */
=FILTER(A2:E500, (B2:B500="挤压组") * ((D2:D500="合格") + (D2:D500="待检")))

/* 筛选后只返回第1列和第5列 */
=CHOOSECOLS(FILTER(A2:E500, B2:B500="挤压组"), 1, 5)

/* 按表头名动态取列 */
=CHOOSECOLS(
    FILTER(A2:E500, B2:B500="挤压组"),
    XMATCH("编号", A1:E1),
    XMATCH("产量", A1:E1)
)

/* 从合格记录中查找指定编号的产量 */
=LET(
    合格集, FILTER(A2:E500, D2:D500="合格"),
    XLOOKUP(G1, INDEX(合格集, 0, 1), INDEX(合格集, 0, 5), "无")
)

/* 筛选挤压组产量最高的前3条 */
=TAKE(
    SORT(FILTER(A2:E500, B2:B500="挤压组"), 5, -1),
    3
)
/* SORT 第5列降序(-1) → TAKE 取前3行 */

/* 挤压组合格产量总和 */
=SUM(FILTER(E2:E500, (B2:B500="挤压组") * (D2:D500="合格")))

/* 挤压组合格记录数 */
=COUNT(FILTER(E2:E500, (B2:B500="挤压组") * (D2:D500="合格")))

/* 挤压组合格率 */
=LET(
    合格数, COUNT(FILTER(E2:E500, (B2:B500="挤压组") * (D2:D500="合格"))),
    总数, COUNT(FILTER(E2:E500, B2:B500="挤压组")),
    IF(总数=0, 0, 合格数/总数)
)

/* 行筛选组别=挤压组，列只取编号和产量 */
=CHOOSECOLS(
    FILTER(A2:E500, B2:B500="挤压组"),
    XMATCH("编号", A1:E1),
    XMATCH("产量", A1:E1)
)

/* 提取挤压组的不重复编号列表 */
=UNIQUE(FILTER(A2:A500, B2:B500="挤压组"))

/* 提取不重复编号并排序 */
=SORT(UNIQUE(FILTER(A2:A500, B2:B500="挤压组")))

/* 一个公式返回编号对应的名称、类型、状态三列 */
=XLOOKUP(A2, B2:B500, C2:E500, "未找到")

/* 自动溢出到 D2:F2 */

/* 匹配以"模具"开头的第一个记录 */
=XLOOKUP("模具*", B2:B500, C2:C500, "未找到", 2)
/* 第5参数=2 表示通配符匹配 */

/* 匹配包含"2026"的记录 */
=XLOOKUP("*2026*", B2:B500, C2:C500, "未找到", 2)

/* 找最后一次出现的记录（最新记录） */
=XLOOKUP(A2, B2:B500, C2:C500, "未找到", 0, -1)
/* 第6参数=-1 表示从后往前搜索 */

/* 查找不超过目标值的最大值（类似 VLOOKUP 模糊匹配） */
=XLOOKUP(A2, B2:B500, C2:C500, "未找到", -1)
/* 第5参数=-1：精确或下一个较小值 */
/* 要求 B 列已升序排列 */

/* 查找不低于目标值的最小值 */
=XLOOKUP(A2, B2:B500, C2:C500, "未找到", 1)
/* 第5参数=1：精确或下一个较大值 */

/* 组别+编号 双条件查找 */
=LET(
    匹配行, (B2:B500=目标组) * (A2:A500=目标编号),
    FILTER(C2:C500, 匹配行, "未找到")
)

/* 或用 XLOOKUP + 数组拼接 */
=XLOOKUP(目标组 & 目标编号, B2:B500 & A2:A500, C2:C500, "未找到")

/* 先在表1查，查不到再查表2 */
=LET(
    结果1, XLOOKUP(A2, Sheet1!B:B, Sheet1!D:D, ""),
    IF(结果1 <> "", 结果1, XLOOKUP(A2, Sheet2!A:A, Sheet2!C:C, "未找到"))
)

/* 每组取产量最高的前3条 */
=LET(
    数据, A2:E500,
    组别, INDEX(数据, 0, 2),
    产量, INDEX(数据, 0, 5),
    排名, MAP(组别, 产量, LAMBDA(g, p,
        SUM((组别=g) * (产量>p)) + 1
    )),
    FILTER(数据, 排名 <= 3)
)

/* 一个公式替代整列 VLOOKUP 下拉 */
=MAP(A2:A100, LAMBDA(编号,
    XLOOKUP(编号, 查找表!A:A, 查找表!D:D, "")
))

/* 表头固定，数据动态筛选 */
=LET(
    表头, A1:E1,
    数据, FILTER(A2:E500, B2:B500="挤压组"),
    VSTACK(表头, 数据)
)

/* 一个编号对应多条记录，合并为逗号分隔 */
=TEXTJOIN(", ", TRUE,
    FILTER(C2:C500, A2:A500=目标编号, "")
)

/* 嵌套 IFERROR 或用 XLOOKUP 第4参数 */
=IFERROR(XLOOKUP(A2, B:B, D:D), "未找到")

/* 或直接用 XLOOKUP 内置 */
=XLOOKUP(A2, B:B, D:D, "未找到")

/* 高亮当前行是否在筛选结果中（条件格式公式） */
=COUNTIF(FILTER($A$2:$A$500, $B$2:$B$500="挤压组"), $A2) > 0

/* 高亮重复值（条件格式） */
=COUNTIF($A$2:$A$500, $A2) > 1
